const fs=require('fs');
const path=require('path');
const cp=require('child_process');
const {chromium}=require('@playwright/test');

const TARGET='assets/css/pages/chat-thread-interaction-contract.css';
const TARGET_SHA=process.env.TARGET_SHA;
const TARGET_BLOB=process.env.TARGET_BLOB;
const PAGES=[
  {page:'mensagens.html',foundation:'assets/css/pages/messaging-foundation.css',runtime:'assets/css/pages/messaging-runtime-chat.css',kind:'messages'},
  {page:'comunidade-interna.html',foundation:'assets/css/pages/comunidade-interna-foundation.css',runtime:'assets/css/pages/comunidade-interna-runtime-chat.css',kind:'community'}
];
const VIEWPORTS=[359,430,759,760,761,1024,1280];
const sh=cmd=>cp.execSync(cmd,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(ok,msg)=>{if(!ok)throw new Error(msg);};

function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v);}return out;}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8'));const tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css')));const direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort(),expected=PAGES.map(p=>p.runtime).sort();assert(JSON.stringify(direct)===JSON.stringify(expected),`target importer drift ${JSON.stringify(direct)}`);for(const p of PAGES){assert(importsFor(p.foundation,tracked).includes(p.runtime),`${p.page} foundation runtime drift`);assert(importsFor(p.runtime,tracked).includes(TARGET),`${p.page} runtime target missing`);const html=fs.readFileSync(p.page,'utf8'),base=path.posix.basename(p.foundation).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');assert((html.match(new RegExp(`assets/css/pages/${base}\\?v=`,'g'))||[]).length===1,`${p.page} foundation link drift`);}const reached=[];for(const p of report.pageAssets){const seen=new Set(),stack=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(stack.length){const f=stack.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break;}for(const n of importsFor(f,tracked))stack.push(n);}if(hit)reached.push(p.page);}assert(JSON.stringify(reached.sort())===JSON.stringify(PAGES.map(p=>p.page).sort()),`active reach drift ${JSON.stringify(reached)}`);console.log(`STATIC REACH PASS|pages=${reached.sort().join(',')}|importers=${expected.join(',')}|target=${TARGET}`);}
function verifyDead(parsed){assert(parsed.declarations.length===303,`declaration drift ${parsed.declarations.length}`);assert(parsed.dead.length===8,`dead drift ${parsed.dead.length}`);const body='body[data-page="mensagens"] .messages-order-card--inline .messages-order-card__body';const actions='body[data-page="mensagens"] .messages-order-card--inline .messages-order-card__actions';const expected=[[body,'display','grid','grid'],[body,'grid-template-columns','minmax(0, 1fr) auto','minmax(104px, 132px) minmax(0, 1fr) auto'],[body,'gap','14px','12px'],[body,'align-items','end','stretch'],[actions,'justify-content','flex-end','flex-start'],[actions,'min-width','max-content','0'],[body,'grid-template-columns','minmax(0, 1fr)','minmax(104px, 132px) minmax(0, 1fr) auto'],[body,'align-items','start','stretch']];for(let i=0;i<expected.length;i++){const d=parsed.dead[i],e=expected[i];assert(d.selector===e[0],`selector ${i} drift ${d.selector}`);assert(d.property===e[1],`property ${i} drift ${d.property}`);assert(d.value===e[2]&&!d.important,`value ${i} drift ${d.value}`);assert(d.context==='',`context ${i} drift ${d.context}`);assert(d.winnerValue===e[3]&&!d.winnerImportant,`winner ${i} drift ${d.winnerValue}`);assert(d.winnerLine>d.line,`winner order ${i}`);}const families=new Set(parsed.dead.map(d=>d.selector));assert(families.size===2,`family drift ${families.size}`);const identical=parsed.dead.filter(d=>d.value===d.winnerValue).length;assert(identical===1,`identical drift ${identical}`);console.log(`DEAD ROWS PASS|decl=303|dead=8|families=2|identical=1|changed=7|lines=${parsed.dead.map(d=>d.line).join(',')}|winnerLines=${parsed.dead.map(d=>d.winnerLine).join(',')}`);}
function removeDead(parsed){const src=fs.readFileSync(TARGET,'utf8'),finalNewline=/\r?\n$/.test(src);const lines=src.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();for(const d of [...parsed.dead].sort((a,b)=>b.line-a.line)){const line=lines[d.line-1];assert(line&&line.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}: ${line}`);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(finalNewline?'\n':''));const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='8'&&stat[2]===TARGET,`unexpected diff ${stat.join(' ')}`);const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===295,`after declarations ${after.declarations.length}`);assert(after.dead.length===0,`after dead ${after.dead.length}`);console.log('EPHEMERAL DELTA PASS|file=chat-thread-interaction-contract.css|additions=0|deletions=8|decl=303->295|dead=8->0');}
async function prepareMessages(page,state){await page.evaluate(state=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');document.body.dataset.page='mensagens';const root=document.querySelector('[data-messages-page]');if(root){root.removeAttribute('aria-busy');root.dataset.viewState='ready';root.hidden=false;}const skeleton=document.querySelector('[data-messages-hydration-skeleton]');if(skeleton)skeleton.hidden=true;document.querySelectorAll('[data-messages-hydration-ready]').forEach(el=>el.hidden=false);let host=document.querySelector('.messages-thread__body');if(!host){host=document.createElement('div');host.className='messages-thread__body';document.body.appendChild(host);}host.hidden=false;document.querySelector('#ux043-order-card')?.remove();const card=document.createElement('article');card.id='ux043-order-card';card.className='messages-order-card--inline';const title=state==='long'?'Reforma completa de cozinha com instalação, acabamento e revisão final detalhada':'Instalação elétrica residencial';card.innerHTML=`<div class="messages-order-card__head"><span>Pedido vinculado</span><strong>#DK-043</strong></div><div class="messages-order-card__body"><div class="messages-order-card__content"><h2>${title}</h2><dl class="messages-order-card__facts"><div><dt>Valor</dt><dd>R$ 480</dd></div><div><dt>Prazo</dt><dd>2 dias</dd></div><div><dt>Status</dt><dd>Aceito</dd></div></dl></div><div class="messages-order-card__actions"><button class="messages-order-card__button messages-order-card__button--ghost" type="button">Detalhes</button><button class="messages-order-card__button" type="button">Continuar</button></div></div>`;host.prepend(card);},{state});}
async function prepareCommunity(page){await page.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');document.body.dataset.page='comunidade-interna';const pending=document.querySelector('[data-community-room-pending]');if(pending)pending.hidden=true;const root=document.querySelector('[data-community-room]');if(root)root.hidden=false;});}
async function captureMessages(page,state){return page.evaluate(state=>{const round=n=>Math.round(n*1000)/1000,card=document.querySelector('#ux043-order-card'),body=card?.querySelector('.messages-order-card__body'),actions=card?.querySelector('.messages-order-card__actions'),facts=card?.querySelector('.messages-order-card__facts');if(!card||!body||!actions||!facts)throw new Error('fixture missing');const b=getComputedStyle(body),a=getComputedStyle(actions),c=getComputedStyle(card),br=body.getBoundingClientRect(),ar=actions.getBoundingClientRect(),cr=card.getBoundingClientRect(),fr=facts.getBoundingClientRect();return{page:'mensagens.html',state,card:{display:c.display,width:c.width,maxWidth:c.maxWidth,padding:c.padding,rect:[round(cr.x),round(cr.y),round(cr.width),round(cr.height)]},body:{display:b.display,gridTemplateColumns:b.gridTemplateColumns,gap:b.gap,rowGap:b.rowGap,columnGap:b.columnGap,alignItems:b.alignItems,width:b.width,rect:[round(br.x),round(br.y),round(br.width),round(br.height)]},actions:{display:a.display,justifyContent:a.justifyContent,minWidth:a.minWidth,minInlineSize:a.minInlineSize,gap:a.gap,width:a.width,rect:[round(ar.x),round(ar.y),round(ar.width),round(ar.height)]},facts:{rect:[round(fr.x),round(fr.y),round(fr.width),round(fr.height)]},doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyScrollWidth:document.body.scrollWidth}};},{state});}
async function captureCommunity(page){return page.evaluate(()=>{const round=n=>Math.round(n*1000)/1000,thread=document.querySelector('.community-room-thread__body'),composer=document.querySelector('.community-room-composer'),tr=thread?.getBoundingClientRect(),cr=composer?.getBoundingClientRect();return{page:'comunidade-interna.html',state:'control',thread:thread?{display:getComputedStyle(thread).display,rect:[round(tr.x),round(tr.y),round(tr.width),round(tr.height)]}:null,composer:composer?{display:getComputedStyle(composer).display,gridTemplateColumns:getComputedStyle(composer).gridTemplateColumns,rect:[round(cr.x),round(cr.y),round(cr.width),round(cr.height)]}:null,doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyScrollWidth:document.body.scrollWidth}};});}
async function capture(browser,tag){const out={};let samples=0;for(const spec of PAGES){const states=spec.kind==='messages'?['short','long']:['control'];for(const state of states){for(const width of VIEWPORTS){const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'});const page=await context.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url());const local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort();});await page.goto(`http://127.0.0.1:4173/${spec.page}?ux043-${tag}-${state}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});if(spec.kind==='messages')await prepareMessages(page,state);else await prepareCommunity(page);await page.waitForTimeout(30);const snap=spec.kind==='messages'?await captureMessages(page,state):await captureCommunity(page);assert(snap.doc.scrollWidth<=snap.doc.clientWidth+1,`horizontal overflow ${tag} ${spec.page} ${state} ${width} ${JSON.stringify(snap.doc)}`);out[`${spec.page}:${state}:${width}`]=snap;samples++;await context.close();}}}console.log(`RUNTIME CAPTURE|tag=${tag}|pages=2|messageStates=2|communityControls=1|viewports=${VIEWPORTS.join(',')}|samples=${samples}|overflow=0`);return out;}
(async()=>{assert(TARGET_SHA&&TARGET_BLOB,'missing env');assert(sh('git rev-parse HEAD')===TARGET_SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');verifyReach();const parsed=parse(fs.readFileSync(TARGET,'utf8'));verifyDead(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');console.log(`CASCADE RUNTIME PARITY PASS|runtimeDiffs=0|overflow=0|families=2/2|reachPages=2|functionalPage=mensagens.html|controlPage=comunidade-interna.html|messageStates=2|viewports=${VIEWPORTS.length}|samples=${Object.keys(before).length}|boundary=759/760/761|staticCascadeRows=8|identicalWinners=1|changedWinners=7`);}finally{await browser.close();}}finally{server.kill('SIGTERM');}sh(`git reset --hard ${TARGET_SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===TARGET_SHA,'restore HEAD drift');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'restore blob drift');assert(sh('git status --porcelain')==='','restore dirty');console.log(`CHECKPOINT PASS|sha=${TARGET_SHA}|productMutation=0|issueCreated=0|prCreated=0`);})().catch(e=>{console.error(e.stack||e);process.exit(1);});
